import{_ as i,a0 as l,w as a,s as p,ao as u,I as n,x as e,a1 as s,A as o}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const y=JSON.parse('{"title":"幼犬式免費：免費軟件中的無形消費 | LCTT x X-CMD","titleTemplate":false,"description":"幼犬式免費：免費軟件中的無形消費 | LCTT (201707) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"幼犬式免費：免費軟件中的無形消費 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"幼犬式免費：免費軟件中的無形消費 | LCTT (201707) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201707/20170213 Free as in puppy The hidden costs of free software","title":"幼犬式免費：免費軟件中的無形消費","tag":"201707","desc":""},"relativePath":"201707/20170213 Free as in puppy The hidden costs of free software.md","filePath":"[post].md"}'),d={name:"201707/20170213 Free as in puppy The hidden costs of free software.md"};function g(f,t,m,T,h,C){const r=l("Link");return a(),p("div",null,[t[13]||(t[13]=u('<h1 id="幼犬式免費-免費軟件中的無形消費" tabindex="-1">幼犬式免費：免費軟件中的無形消費 <a class="header-anchor" href="#幼犬式免費-免費軟件中的無形消費" aria-label="Permalink to “幼犬式免費：免費軟件中的無形消費”">​</a></h1><p><img src="https://opensource.com/sites/default/files/styles/image-full-size/public/images/business/osdc_whitehurst_money.png?itok=Xqow4bzq" alt="幼犬式免費：免費軟件中的無形消費" title="幼犬式免費: 免費軟件中的無形消費"></p><p>Image by : opensource.com</p><p>我們習慣於軟件被描述為“<ruby>自由式免費<rt>free as in freedom</rt></ruby>”和“<ruby>啤酒式免費<rt>free as in beer</rt></ruby>”。但還有另一種不常被提起的“免費”——“<ruby>幼犬式免費<rt>free as in puppy</rt></ruby>”。這個概念來自於當別人送你一隻免費的小狗，但那隻小狗不是真的免費。日常照顧它需要花費大量精力與金錢。商業術語是“總體擁有成本”，即 TCO ，這適用於所有場景，不僅僅是開源軟件和小狗。</p><p>既然免費小狗問題適用於所有事，那麼它是如何對於開源軟件特別重要的呢？有一些解釋。首先，如果你已經購買了軟件，就會因為消費對它設定期望值。軟件起初免費後來需要花錢似乎是很無理的要求。其次，如果這發生在一個組織首次採用開源項目的時候，就會阻礙該組織下一次採用開源項目。最終且違反直覺的是，看起來開源軟件需要花錢可能使得它更輕易“賣出”，如果它真的免費，未免也太好了一點。</p><p>接下來的部分是軟件消費漸顯的共同之處。這絕不是一個詳盡的列表。</p><h3 id="起始消費" tabindex="-1">起始消費 <a class="header-anchor" href="#起始消費" aria-label="Permalink to “起始消費”">​</a></h3><p>開始使用軟件之前，你必須首先擁有這個軟件。</p><ul><li><strong>軟件：</strong> 因為它是開源的不一定意味着它是_免費的_。</li><li><strong>硬件：</strong> 考慮到軟件的需求。如果你沒有使用軟件所需的硬件（可能是服務器硬件或者客户端硬件），你得買。</li><li><strong>培訓：</strong> 很少有軟件完全直白如話的。在於你是選擇培訓還是自己去弄清楚。</li><li><strong>實戰：</strong> 把所有零部件放在一起只是開始，現在，是時候把所有東西拼在一起了。 <ul><li><strong>安裝和配置：</strong> 至少這將花費一些員工的工作時間。如果這是一個大項目，你可能需要花錢請一個系統整合服務商或者其他供應商來做這件事。</li><li><strong>數據導入：</strong> 如果要取代現成的系統，存在數據搬家的問題。皆大歡喜的是所有都是相同標準編譯的，這樣就沒什麼問題。然而在很多情況，需要寫一些腳本來提取和重載數據。</li><li><strong>其他系統的接口：</strong> 説到寫腳本，這個軟件能和你使用的其他軟件（例如，目錄服務或者工資軟件）很好聯繫起來嗎？</li><li><strong>定製：</strong> 如果原本的軟件不能滿足你所有的需求，那它可能需要定製。你可以做到，但是仍需要努力或者是一些原材料。</li></ul></li><li><strong>商業變化：</strong> 當你的組織希望有所提升時，新軟件也可能會變化。然而這種轉換不是免費的。例如，生產效率剛開始可能會下降因為員工還在適應新軟件。</li></ul><h3 id="經營成本" tabindex="-1">經營成本 <a class="header-anchor" href="#經營成本" aria-label="Permalink to “經營成本”">​</a></h3><p>安裝軟件是簡單部分，現在你得使用它。</p><ul><li><strong>更多培訓：</strong> 什麼，你認為我們已經做好了? 過段時間，你的組織會加入新人，他們需要學習如何使用這個軟件，或者説是添加了額外功能的新版本軟件發佈了。</li><li><strong>維護：</strong><ul><li><strong>訂閲費：</strong> 有些軟件通過收取訂閲費來提供更新。</li><li><strong>補丁：</strong>取決於軟件的自身，打補丁需要費很多功夫。包括測試和部署。</li><li><strong>開發：</strong>你自己做所有定製嗎？現在你必須維護下去了。</li></ul></li><li><strong>支持：</strong> 當它壞了得有人來修，無論是供應商還是自己的團隊，確實需要一筆花費。</li><li><strong>良好的做法：</strong> 這個不是必需品，但如果你在使用開源軟件，無論如何給一些回饋是非常好的。比如代碼貢獻、在郵件列表提供支持、贊助年度會議等等。</li><li><strong>商業利益：</strong> 好吧，這不是一個付費項，而且它抵消了一些費用。使用軟件對你的組織意味着什麼呢？如果它使得量產產品減少了 25% 的浪費，這就是價值。再換個例子，它可能幫助你減少 30% 不盈利部分。</li></ul><p>這樣例子數不勝數，確實需要一定想像力來想出所有的花費。算出正確的價值需要一些實驗和大量的的優質客户，但是這樣分析一遍的話會使得它更加清晰。就好像一隻小狗狗，如果預先知道自己會付出多少，這可能會是一個有價值的實驗。</p><hr><p>作者簡介：</p><p>Ben Cotton - Ben Cotton 是一個培訓過的氣象學家和一個職業的高效計算機工程師。 Ben 在 Cycle Computing 做技術傳教士。他是 Fedora 用户和貢獻者，合作創辦當地的一個開源集會，是一名開源倡議者和軟件自由機構的支持者。他的推特 (@FunnelFiasco)</p><hr>',17)),n("p",null,[t[1]||(t[1]=e("via: ",-1)),s(r,{href:"https://opensource.com/article/17/2/hidden-costs-free-software"},{default:o(()=>[...t[0]||(t[0]=[e("https://opensource.com/article/17/2/hidden-costs-free-software",-1)])]),_:1})]),n("p",null,[t[5]||(t[5]=e("作者：",-1)),s(r,{href:"https://opensource.com/users/bcotton"},{default:o(()=>[...t[2]||(t[2]=[e("Ben Cotton",-1)])]),_:1}),t[6]||(t[6]=e(" 譯者：",-1)),s(r,{href:"https://github.com/XYenChi"},{default:o(()=>[...t[3]||(t[3]=[e("XYenChi",-1)])]),_:1}),t[7]||(t[7]=e(" 校對：",-1)),s(r,{href:"https://github.com/wxy"},{default:o(()=>[...t[4]||(t[4]=[e("wxy",-1)])]),_:1})]),n("p",null,[t[10]||(t[10]=e("本文由 ",-1)),s(r,{href:"https://github.com/LCTT/TranslateProject"},{default:o(()=>[...t[8]||(t[8]=[e("LCTT",-1)])]),_:1}),t[11]||(t[11]=e(" 原創編譯，",-1)),s(r,{href:"https://linux.cn/"},{default:o(()=>[...t[9]||(t[9]=[e("Linux中國",-1)])]),_:1}),t[12]||(t[12]=e(" 榮譽推出",-1))])])}const x=i(d,[["render",g]]);export{y as __pageData,x as default};
